function decodeResponse(raw){
 if(typeof raw!=='string'||!raw.trim())throw Error('Respons pelayan kosong. Pastikan Code.gs dan Index.html versi terkini telah disimpan, kemudian Deploy > Manage deployments > Edit > New version > Deploy. Buka semula pautan /exec.');
 let response;try{response=JSON.parse(raw)}catch(e){throw Error('Respons pelayan tidak sah. Kemas kini kedua-dua fail dan terbitkan New version.');}
 if(!response||response.ok!==true){throw Error(response?.error||'Pelayan tidak memulangkan data yang sah.');}
 if(response.data===null||response.data===undefined)throw Error('Data pelayan kosong. Sila buka semula pautan /exec selepas deployment dikemas kini.');
 return response.data;
}
function rpc(method,...args){return window.BarsaBridge.call(method,args).then(decodeResponse);}
function checkedStateResponse(x){if(!x||typeof x!=='object'||!x.state||!x.state.groups||!x.state.timetables||!Array.isArray(x.state.history)||!Array.isArray(x.state.submissions)||!Number.isInteger(x.revision))throw Error('Data konfigurasi pelayan tidak lengkap. Kemas kini Code.gs dan Index.html serta deployment, kemudian log masuk semula.');return x;}
