async function refreshCloud(){await saveChain;if(saveFailed)throw Error('Simpanan terdahulu gagal. Muat semula halaman dan log masuk semula.');let x=checkedStateResponse(await rpc('loadState',authToken));db=x.state;serverRevision=x.revision;db.aliases??={};return x;}
