$('teacherStatusList').onchange=safe(async e=>{let name=e.target.dataset.teacherStatus;if(!name)return;let select=e.target;select.disabled=true;db.longLeave??={};if(select.value==='leave')db.longLeave[norm(name)]=true;else delete db.longLeave[norm(name)];try{await save();invalidate();refreshMembers();auditCapacity();say('Status '+name+' disimpan. Jana semula jadual menggunakan ahli aktif.');}finally{select.disabled=false;}});
