async function uploadTT(file){let tt={};if(file.name.endsWith('.json')){let j=JSON.parse(await file.text());tt=j.timetables||j;for(let [n,t] of Object.entries(tt)){if(!t.busy||!DAYS.every(d=>Array.isArray(t.busy[d])&&t.busy[d].every(v=>Array.isArray(v)&&v.length===2&&v.every(Number.isFinite)&&v[1]>v[0])))throw Error('Format jadual JSON tidak sah: nama -> busy -> hari -> [[minit mula, minit tamat]].')}}else if(file.name.endsWith('.pdf')){let pages=await pdfPages(file);for(let p of pages){let sx=p.width/841.92,sy=p.height/595.32;let its=p.items.map(i=>({...i,x:i.x/sx,y:i.y/sy,w:i.w/sx}));let names=its.filter(i=>i.x>440&&i.y>44&&i.y<74);let name=clean(lineText(names));if(!name||!/\b(BIN|BINTI|BT)\b|A\s*\/\s*[LP]/.test(name))continue;let days=DAYS.map(d=>its.find(i=>i.text===d&&i.x<100));if(days.some(x=>!x))continue;let times=lines(its.filter(i=>i.y>90&&i.y<112)).map(r=>r.text).join(' ');let ranges=[...times.matchAll(/(\d{1,2}:\d{2})\s*-\s*(\d{1,2}:\d{2})/g)].map(m=>m.slice(1).map(v=>{let[h,mi]=v.split(':').map(Number);return(h<11?h+12:h)*60+mi}));if(ranges.length!==10)continue;let busy={};DAYS.forEach((d,di)=>{let cy=days[di].y,top=di?((days[di-1].y+cy)/2):110,bottom=di<4?((cy+days[di+1].y)/2):369;let texts=its.filter(i=>i.x>=98&&i.x<824&&i.y>top&&i.y<bottom&&!/SOLAT JUMAAT/.test(i.text));let set=new Set();texts.forEach(it=>{let first=Math.max(0,Math.min(9,Math.floor((it.x-98)/72.5))),last=Math.max(first,Math.min(9,Math.floor((it.x+it.w-99)/72.5)));for(let j=first;j<=last;j++)set.add(j)});busy[d]=[...set].map(j=>d==='JUMAAT'&&j>=2?[[870,900],[900,930],[930,960],[960,980],[980,1010],[1010,1040],[1040,1070],[1070,1100]][j-2]:ranges[j])});tt[name]={busy,reviewed:false};}
 }else throw Error('Gunakan PDF bertulis aSc seperti lampiran, atau JSON jadual. PDF imbasan perlu diisi melalui semakan manual.');if(!Object.keys(tt).length)throw Error('Tiada jadual dapat dibaca. Format PDF berlainan atau PDF imbasan: gunakan semakan kekosongan manual / JSON. Jadual lama dikekalkan.');db.pending={name:file.name,data:tt,uploaded:new Date().toLocaleString('ms-MY')};await save();renderPending();$('importStatus').textContent='Bacaan selesai. Aktifkan versi baharu selepas menyemak maklumat.';}
