$('saveGroup').onclick=safe(async()=>{let k=$('adminGroup').value,ns=$('groupText').value.split('\n').map(clean).filter(Boolean);if(!ns.length)throw Error('Masukkan sekurang-kurangnya seorang guru.');if(new Set(ns.map(norm)).size!==ns.length)throw Error('Terdapat nama guru berulang.');if(Object.entries(db.groups).some(([g,v])=>g!==k&&v.some(n=>ns.some(m=>norm(m)===norm(n)))))throw Error('Guru ini sudah ada dalam kumpulan lain. Betulkan kumpulan lama dahulu.');db.groups[k]=ns;await save();init();auditCapacity();say('Nama ahli kumpulan disimpan.');});
