$('restore').onchange=safe(async e=>{let f=e.target.files[0];if(!f)return;let v=JSON.parse(await f.text());if(v.schema!==1||!v.groups||!v.quotas||!v.times||!Array.isArray(v.history)||!v.availability||!v.timetables||!Array.isArray(v.submissions)||!roles.every(r=>Number.isInteger(v.quotas[r.id])&&v.quotas[r.id]>=0&&v.quotas[r.id]<=50)||!Object.values(v.groups).every(ns=>Array.isArray(ns)&&ns.every(n=>typeof n==='string'))||!['normal','friday'].every(t=>Object.keys(DEFAULT_TIMES[t]).every(p=>Array.isArray(v.times[t]?.[p])&&v.times[t][p].length===2&&v.times[t][p].every(x=>/^\d\d:\d\d$/.test(x)))))throw Error('Fail sandaran tidak sah.');if(!confirm('Pulihkan sandaran ini? Data semasa pelayar akan digantikan. Eksport sandaran semasa dahulu jika perlu.'))return;v.history=db.history;v.submissions=db.submissions;db=v;await save();invalidate();init();auditCapacity();say('Tetapan sandaran dipulihkan. Sejarah bersama Google Sheets dikekalkan.');e.target.value=''});
